Author:     Welpy-cw <58345540+Welpy-cw@users.noreply.github.com>
AuthorDate: Tue Aug 25 17:10:05 2026 +0100
Commit:     brendan@thunderbird.net <brendan@thunderbird.net>
CommitDate: Tue Aug 25 17:19:06 2026 +0000

    Bug 2065806 - Keep MSG_VIEW_FLAG_ISTHREAD on single-message thread roots. r=mkmelin

    When deleting a message left a thread with only its root, the view
    stripped MSG_VIEW_FLAG_ISTHREAD from the root row along with Elided and
    MSG_VIEW_FLAG_HASCHILDREN. The twisty correctly disappeared, but
    ISTHREAD is not just a UI hint: ReverseThreads() uses it to find thread
    boundaries when reversing the sort order. With the flag gone, a later
    sort-order toggle dropped the root row from m_keys/m_flags/m_levels,
    making the message vanish from the list until the folder was re-entered
    or compacted.

    Keep ISTHREAD and clear only Elided | HASCHILDREN - that is sufficient
    to flatten the row in the UI (expand/collapse already requires both
    HASCHILDREN and ISTHREAD). Fixed in two places:
    - nsMsgDBView::OnHdrDeleted() (message deleted while hidden in a
      collapsed thread)
    - nsMsgThreadedDBView::RemoveByIndex() (visible message deleted)

    The same pattern exists in nsMsgSearchDBView::RemoveByIndex() but was
    left alone: cross-folder threads couldn't be made to exhibit the bug.

    Based on research by alta88.

    Differential Revision: https://phabricator.services.mozilla.com/D320680

diff --git a/mail/test/browser/folder-display/browser_deletionFromThreads.js b/mail/test/browser/folder-display/browser_deletionFromThreads.js
index ddd4269aff4..9e7c7266510 100644
--- a/mail/test/browser/folder-display/browser_deletionFromThreads.js
+++ b/mail/test/browser/folder-display/browser_deletionFromThreads.js
@@ -442,3 +442,81 @@ add_task(async function test_cross_tab_phantom_twisty() {

   await close_tab(tab2);
 });
+
+/**
+ * Bug 2065806 - Deleting the only child of a thread and then sorting must not
+ * remove the parent message from the view.
+ *
+ * When a delete left only the thread root, MSG_VIEW_FLAG_ISTHREAD was
+ * stripped from the root row along with Elided/HASCHILDREN. Sorting relies
+ * on ISTHREAD to find thread boundaries, so the root was silently dropped
+ * from the view until the folder was re-entered.
+ */
+add_task(async function test_delete_only_child_then_sort() {
+  // Setup a folder with exactly 2 messages in a thread (root + one child).
+  const structFolder = await create_folder("StructFolder_SortAfterDelete");
+  await make_message_sets_in_folders(
+    [structFolder],
+    [{ count: 2, msgsPerThread: 2 }]
+  );
+
+  await switch_tab(tab1);
+  await be_in_folder(structFolder);
+  await make_display_threaded();
+  await collapse_all_threads();
+
+  const dbView =
+    document.getElementById("tabmail").currentTabInfo.chromeBrowser
+      .contentWindow.gDBView;
+
+  Assert.equal(dbView.rowCount, 1, "Collapsed thread should show 1 row");
+
+  // Expand, delete the child (row 1), leaving only the root.
+  await expand_all_threads();
+  Assert.equal(dbView.rowCount, 2, "Expanded thread should show 2 rows");
+  await select_click_row(1);
+  await press_delete();
+
+  Assert.equal(dbView.rowCount, 1, "Only the root should remain");
+  Assert.ok(
+    !dbView.isContainer(0),
+    "Root should have lost the twisty after child deletion"
+  );
+
+  // Remember the root's message ID before sorting so we can verify it
+  // survives the sort.
+  const rootMessageId = dbView.getMsgHdrAt(0).messageId;
+
+  // Toggle the sort order on the date column. This exercises both the view
+  // rebuild path and ReverseThreads(), which needs ISTHREAD to find thread
+  // boundaries. The root must survive both directions.
+  const sortType = Ci.nsMsgViewSortType.byDate;
+  dbView.sort(sortType, Ci.nsMsgViewSortOrder.descending);
+  Assert.equal(
+    dbView.rowCount,
+    1,
+    "Root should still be visible after sorting descending"
+  );
+  Assert.equal(
+    dbView.getMsgHdrAt(0).messageId,
+    rootMessageId,
+    "The surviving row should still be the thread root"
+  );
+  dbView.sort(sortType, Ci.nsMsgViewSortOrder.ascending);
+  Assert.equal(
+    dbView.rowCount,
+    1,
+    "Root should still be visible after toggling sort back to ascending"
+  );
+  Assert.equal(
+    dbView.getMsgHdrAt(0).messageId,
+    rootMessageId,
+    "The surviving row should still be the thread root"
+  );
+  Assert.ok(
+    !dbView.isContainer(0),
+    "Root remains a single-message row without twisty"
+  );
+
+  structFolder.deleteSelf(null);
+});
diff --git a/mail/test/browser/folder-display/browser_deletionWithMultipleDisplays.js b/mail/test/browser/folder-display/browser_deletionWithMultipleDisplays.js
